DecodeResult DecoderImpl::decodeVWmmaScaleF32Vop3px2(const MachineInst *opcode,
                                                     const DecodeErrorEmitter &emit_error) {
  if (!isVop3pOp(opcode[2], 0x33) && !isVop3pOp(opcode[2], 0x88))
    return decodeInvalid(opcode, emit_error);
  if (!isGfx1250WmmaScalePairValid(opcode))
    return decodeInvalid(opcode, emit_error);
  return std::make_unique<VWmmaScaleF32Vop3px2>(opcode);
}

DecodeResult DecoderImpl::subDecodeVimage(const MachineInst *opcode,
                                          const DecodeErrorEmitter &emit_error) {
  Vimage::OpEncoding op = *reinterpret_cast<const decltype(op) *>(opcode);
#if RJ_HOST_HAS_X86_64_ELF_REL32
  return sub_decode_vimage[op.op](opcode, emit_error);
#else
  switch (static_cast<unsigned>(op.op)) {
  case 196:
    return detail::decodeTensorLoadToLdsVimage(opcode, emit_error);
  case 197:
    return detail::decodeTensorStoreFromLdsVimage(opcode, emit_error);
  default:
    return DecoderImpl::decodeInvalid(opcode, emit_error);
  }
#endif
}

